#!/usr/bin/env node

/**
 * This script reads the built hydroxide packages and generates a TypeScript file
 * that exports them as strings for use in Sandpack.
 */

import { readFileSync, writeFileSync, existsSync } from 'fs'
import { dirname, join } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const rootDir = join(__dirname, '..', '..')

const hydroxidePath = join(rootDir, 'packages/core/dist/dev-esm.js')
const hydroxideDomPath = join(rootDir, 'packages/web/renderer/dist/dev-esm.js')

// Check if bundles exist
if (!existsSync(hydroxidePath)) {
  console.error('Error: hydroxide bundle not found. Run `pnpm run build:all` first.')
  process.exit(1)
}

if (!existsSync(hydroxideDomPath)) {
  console.error('Error: hydroxide-dom bundle not found. Run `pnpm run build:all` first.')
  process.exit(1)
}

// Read bundle contents
const hydroxideBundle = readFileSync(hydroxidePath, 'utf-8')
const hydroxideDomBundle = readFileSync(hydroxideDomPath, 'utf-8')

// Generate TypeScript file
const output = `// AUTO-GENERATED FILE - DO NOT EDIT
// Generated by scripts/generate-local-bundles.js
// Run \`pnpm run generate:bundles\` to regenerate

export const hydroxideBundle = ${JSON.stringify(hydroxideBundle)}

export const hydroxideDomBundle = ${JSON.stringify(hydroxideDomBundle)}
`

const outputPath = join(__dirname, '..', 'src/lib/local-bundles.ts')
writeFileSync(outputPath, output)

console.log('Generated local-bundles.ts successfully!')
